import { getArticleList } from '@/apis/content'
import ExcelTable from '@/components/exportExcel'
import {
    ProFormDateRangePicker
} from '@ant-design/pro-components'
import { Button, Tag } from 'antd'
import { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'

const ArticleManagement: React.FC = () => {
    const navigate = useNavigate()

    // 修正状态映射（根据Content.ArticleItem.status定义）
    const statusMap = [
        <Tag color="orange" key='orange' style={{ marginInlineEnd: 0 }}>待审核</Tag>,
        <Tag color="green" key='green' style={{ marginInlineEnd: 0 }}>已通过</Tag>,
        <Tag color="red" key='red' style={{ marginInlineEnd: 0 }}>已拒绝</Tag>
    ]

    return (
        <ExcelTable key='article'
            columns={[
                {
                    title: '标题',
                    dataIndex: 'title',
                    hideInSearch: false,
                    onFilter: true,
                    ellipsis: true
                },
                {
                    title: '点赞量',
                    dataIndex: 'likeCount',
                    hideInSearch: true,
                    width: 80,
                    align: 'center',
                    render: (_, record) => record.likeCount || 0
                },
                {
                    title: '浏览量',
                    dataIndex: 'viewCount',
                    hideInSearch: true,
                    width: 80,
                    align: 'center',
                    render: (_, record) => record.viewCount || 0
                },
                {
                    title: '收藏量',
                    dataIndex: 'favoriteCount',
                    hideInSearch: true,
                    width: 80,
                    align: 'center',
                    render: (_, record) => record.favoriteCount || 0
                },
                {
                    title: '状态',
                    dataIndex: 'status',
                    hideInSearch: false,
                    onFilter: true,
                    width: 80,
                    align: 'center',
                    render: (_, record) => statusMap[record.status - 1],
                    valueEnum: {
                        1: {
                            text: '待审核',
                        },
                        2: {
                            text: '已通过',
                        },
                        3: {
                            text: '已拒绝',
                        },
                    }
                },
                {
                    title: '创建者',
                    dataIndex: 'creator',
                    hideInSearch: false,
                    onFilter: true,
                    ellipsis: true,
                },
                {
                    title: '创建时间',
                    dataIndex: 'createdAt',
                    hideInSearch: false,
                    onFilter: true,
                    ellipsis: true,
                    valueType: 'dateTime',
                    renderFormItem: (_, { defaultRender, ...rest }) => {
                        return <ProFormDateRangePicker
                            fieldProps={{
                                value: rest.value,
                                onChange: rest.onChange,
                                showTime: false
                            }}
                        />
                    },
                },
                {
                    title: '审核人',
                    dataIndex: 'reviewer',
                    hideInSearch: true,
                    ellipsis: true,
                    render: (_, record) => record.reviewer || '-'
                },
                {
                    title: '审核时间',
                    dataIndex: 'reviewTime',
                    hideInSearch: true,
                    ellipsis: true,
                    valueType: 'dateTime',
                    render: (_, record) => record.reviewTime || '-'
                },
                {
                    title: '操作',
                    key: 'option',
                    valueType: 'option',
                    width: 70,
                    align: 'center',
                    render: (_, record) => [
                        <Button
                            key={`${record.id}-edit`}
                            type="link"
                            onClick={() => navigate(`/content/article-detail/${record.id}`)}
                        >
                            {record.status === 1 ? '审核' : '查看'}
                        </Button>
                    ]
                }
            ]}
            requestFn={async (params) => {
                const { page, pageSize, categoryId, ...rest } = params
                let createdAtStartDate = null
                let createdAtEndDate = null
                if (!params.createdAt) {
                    createdAtStartDate = null
                    createdAtEndDate = null
                } else {
                    createdAtStartDate = params.createdAt[0].replace('00:00:00', '23:59:59')
                    createdAtEndDate = params.createdAt[1].replace('00:00:00', '23:59:59')
                }
                return await getArticleList({
                    ...rest,
                    page,
                    pageSize,
                    categoryId, // 修正参数名与接口定义一致
                    createdAtStartDate,
                    createdAtEndDate,
                    createdAt: null
                })
            }}
            rowSelection={false}
            options={{
                fullScreen: false,
                reload: true,
                setting: false,
                density: false
            }}
        />
    )
}
export default ArticleManagement